// The emoji picker's data (T05 §4.5): emojibase's emoji in the picker's nine groups, CLDR short names and keywords,
// per locale a lazy chunk (generated by tools/build-emoji.mjs; English only for now, as the UI ships in English).
// Inserted emoji are plain text, so they work wherever the label goes; the OS emoji font draws them.

export interface Emoji {
  /** The emoji itself (default skin tone). */
  e: string;
  /** CLDR short name. */
  name: string;
  /** Search keywords, space-separated. */
  keywords: string;
  /** Takes skin tones (`withTone`). */
  tones: boolean;
}

export interface EmojiGroup {
  /** `smileys`, `people`, `animals`, `food`, `travel`, `activities`, `objects`, `symbols`, `flags`. */
  key: string;
  items: Emoji[];
}

export interface EmojiSet {
  locale: string;
  groups: EmojiGroup[];
}

type Raw = Readonly<Record<string, string>>;

/** The locales there is data for; a UI language without one falls back to English. */
const LOADERS: Readonly<Record<string, () => Promise<Raw>>> = {
  en: () => import('./en.js').then((m) => m.EMOJI),
};

/** The skin tone modifiers (light … dark); tone 0 is the default yellow. */
export const SKIN_TONES = ['\u{1F3FB}', '\u{1F3FC}', '\u{1F3FD}', '\u{1F3FE}', '\u{1F3FF}'] as const;

/** An emoji in skin tone `tone` (1–5; 0 or an emoji without tones: as it is): the modifier after the first code point. */
export function withTone(e: string, tone: number, tones = true): string {
  const mod = SKIN_TONES[tone - 1];
  if (!mod || !tones) return e;
  const cps = [...e];
  return cps[0]! + mod + cps.slice(1).join('').replace(/^️/, '');
}

/** Reads the compact form (`[~]emoji|name|keywords;…` per group). */
export function parseEmoji(raw: Raw, locale = 'en'): EmojiSet {
  return {
    locale,
    groups: Object.entries(raw).map(([key, s]) => ({
      key,
      items: s ? s.split(';').map((entry) => {
        const tones = entry.startsWith('~');
        const [e = '', name = '', keywords = ''] = (tones ? entry.slice(1) : entry).split('|');
        return { e, name, keywords, tones };
      }) : [],
    })),
  };
}

const cache = new Map<string, Promise<EmojiSet>>();

/** Loads the emoji of a locale (`de-CH` → `de` → English). */
export function loadEmoji(locale = 'en'): Promise<EmojiSet> {
  const base = locale.toLowerCase().split(/[-_]/)[0] ?? 'en';
  const key = LOADERS[locale] ? locale : LOADERS[base] ? base : 'en';
  let p = cache.get(key);
  if (!p) {
    p = LOADERS[key]!().then((raw) => parseEmoji(raw, key));
    cache.set(key, p);
    p.catch(() => cache.delete(key));
  }
  return p;
}

const words = (s: string): string[] => s.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean);

/** Emoji whose name or keywords match every word of `q` (a word's prefix), names first. */
export function searchEmoji(set: EmojiSet, q: string, limit = 120): Emoji[] {
  const qs = words(q);
  if (!qs.length) return [];
  const scored: [number, number, Emoji][] = [];
  let n = 0;
  for (const g of set.groups)
    for (const it of g.items) {
      n++;
      const nw = words(it.name), kw = words(it.keywords);
      let score = 0;
      for (const w of qs) {
        const s = nw.includes(w) ? 3 : nw.some((x) => x.startsWith(w)) ? 2 : kw.some((x) => x.startsWith(w)) ? 1 : 0;
        if (!s) {
          score = 0;
          break;
        }
        score += s;
      }
      if (score) scored.push([score, n, it]);
    }
  return scored.sort((a, b) => b[0] - a[0] || a[1] - b[1]).slice(0, limit).map((x) => x[2]);
}
